#!/usr/bin/env bash
# Checks one evaluation task of the agent guides (docs/agent-guidance.md)
# in a project generated by scripts/check-template.sh, after an agent, a
# person or --solution did the task in it. Each step passes, fails or is
# skipped, and every step runs that can:
#
#   own-tests       the project's own tests pass (`cargo test`, no local mode)
#   tests-added     more of them passed than the template has tests
#   build-local     it builds with local mode (`cargo check --all-targets`)
#   build-no-local  and without it
#   static          the task's own checks of the source, if it has any
#   acceptance      acceptance/<task>.rs passes against it
#   run             with --run: the server starts on an embedded Postgres
#                   and answers the task's requests over REST as the task
#                   says (temporal-activity: with Temporal in Docker)
#
# A step that needs a build is skipped after that build failed. The
# summary lists every step; the exit code is 1 when any failed. --result
# FILE writes the outcome as JSON, for run.sh's record.
#
# --solution copies fixtures/<task>/ in and applies solutions/<task>.patch
# first, and afterwards puts the project back exactly as it was (every
# top-level path but target/ and .git, Cargo.toml and Cargo.lock
# included), on success and failure alike. CI does that for every task
# (check-solutions.sh), so a guide, the template and the API can't drift
# apart unnoticed: a reference solution that stops compiling or passing
# fails the build.
#
# One run at a time uses a build directory (CARGO_TARGET_DIR, or the
# project's target/): this takes its lock (lib.sh), waiting if another run
# holds it, unless run.sh, which holds it already, passed it on.
#
# Usage: scripts/agent-guides/eval/check.sh <task> <project-dir> [--solution] [--run]
#        [--result FILE] [--logs DIR]
#        <task>: a name in tasks/ (ls scripts/agent-guides/eval/tasks)
#        --logs DIR: keep the test and server logs there
set -uo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
# shellcheck source=lib.sh
source "$here/lib.sh"
root="$eval_root"

usage='eval-check: usage: check.sh <task> <project-dir> [--solution] [--run] [--result FILE] [--logs DIR]'
task="${1:-}"
app="${2:-}"
solution=false
run=false
result_file=
logs_dir=
shift 2 || { echo "$usage" >&2; exit 2; }
while [[ $# -gt 0 ]]; do
    case "$1" in
        --solution) solution=true ;;
        --run) run=true ;;
        --result)
            [[ $# -ge 2 && -n "$2" ]] || { echo "$usage" >&2; exit 2; }
            result_file="$2"; shift ;;
        --logs)
            [[ $# -ge 2 && -n "$2" ]] || { echo "$usage" >&2; exit 2; }
            logs_dir="$2"; shift ;;
        *) echo "eval-check: unknown argument $1" >&2; exit 2 ;;
    esac
    shift
done
[[ -n "$task" && -f "$here/tasks/$task.md" ]] || { echo "eval-check: no task '$task'" >&2; exit 2; }
[[ -f "$app/Cargo.toml" ]] || { echo "eval-check: $app is not a project" >&2; exit 2; }
app="$(cd "$app" && pwd)"
[[ -z "$result_file" ]] || result_file="$(cd "$(dirname "$result_file")" && pwd)/$(basename "$result_file")"
[[ -z "$logs_dir" ]] || { mkdir -p "$logs_dir" && logs_dir="$(cd "$logs_dir" && pwd)"; }

target="${CARGO_TARGET_DIR:-$app/target}"
mkdir -p "$target"
target="$(cd "$target" && pwd)"
eval_lock "$target" || exit 1
# Nothing this starts keeps the lock after this script is gone.
cargo() { without_lock command cargo "$@"; }
docker() { without_lock command docker "$@"; }
setup_tools || exit 1

# On the disk the build is on, not /tmp: it holds copies of executables.
work="$(mktemp -d "$target/skilj-eval-check.XXXXXX")"
harness="$app/tests/skilj_eval_acceptance.rs"
harness_ours=false
cleanup() {
    local pid container entry
    if [[ -f "$work/pids" ]]; then
        while read -r pid; do
            if kill -0 "$pid" 2>/dev/null; then
                kill -INT "$pid" 2>/dev/null
                sleep 5
                kill -KILL "$pid" 2>/dev/null
            fi
        done < "$work/pids"
    fi
    if [[ -f "$work/containers" ]]; then
        while read -r container; do
            docker rm -f "$container" >/dev/null 2>&1
        done < "$work/containers"
    fi
    if $harness_ours; then rm -f "$harness"; fi
    if $solution && [[ -d "$work/snapshot" ]]; then
        # Exactly as it was: what the solution added goes, what it changed
        # comes back. With new modification times, not the old ones: Cargo
        # takes a source older than its build output for unchanged, and the
        # output in a shared build directory may be of the solution's.
        while IFS= read -r -d '' entry; do
            case "$(basename "$entry")" in target | .git) continue ;; esac
            rm -rf "$entry"
        done < <(find "$app" -mindepth 1 -maxdepth 1 -print0)
        cp -R -P --preserve=mode "$work/snapshot/." "$app/"
    fi
    if [[ -n "$logs_dir" ]]; then
        cp "$work"/*.log "$logs_dir/" 2>/dev/null
    fi
    rm -rf "$work"
}
trap cleanup EXIT
trap 'exit 130' INT TERM

steps=(own-tests tests-added build-local build-no-local static acceptance run)
declare -A status
first_failure=

# fail <message>: ends the step it is called in (each runs in a subshell).
fail() {
    echo "eval-check: $task: $*" >&2
    printf '%s\n' "$*" > "$work/failure"
    exit 1
}

# step <name> <function>: runs it in a subshell, records pass or fail.
step() {
    local name="$1" rc
    shift
    echo "eval-check: $task: $name ..."
    rm -f "$work/failure"
    (set -e; "$@")
    rc=$?
    if [[ $rc -eq 0 ]]; then
        status[$name]=pass
    else
        status[$name]=fail
        if [[ -z "$first_failure" ]]; then
            first_failure="$name: $(cat "$work/failure" 2>/dev/null || echo 'a command failed (see above)')"
        fi
    fi
    echo "eval-check: $task: $name: ${status[$name]}"
}

skip() {
    status[$1]=skipped
    echo "eval-check: $task: $1: skipped ($2)"
}

finish() {
    local name failed=false
    [[ -n "$first_failure" ]] && failed=true
    echo "eval-check: $task: summary"
    for name in "${steps[@]}"; do
        printf '  %-15s %s\n' "$name" "${status[$name]:-unrun}"
        [[ "${status[$name]:-}" == fail ]] && failed=true
    done
    if [[ -n "$result_file" ]]; then
        local pairs=()
        for name in "${steps[@]}"; do pairs+=("$name=${status[$name]:-unrun}"); done
        TASK="$task" FAILURE="$first_failure" python3 - "$result_file" "${pairs[@]}" <<'EOF'
import json, os, sys
steps = dict(pair.split("=", 1) for pair in sys.argv[2:])
with open(sys.argv[1], "w") as out:
    json.dump({"task": os.environ["TASK"], "steps": steps,
               "failure": os.environ["FAILURE"] or None}, out, indent=2)
    out.write("\n")
EOF
    fi
    if $failed; then
        echo "eval-check: $task: FAILED ($first_failure)"
        exit 1
    fi
    if $run; then
        echo "eval-check: $task: OK (ran). Review it by hand as docs/agent-guidance.md lists."
    else
        echo "eval-check: $task: OK (not run). Review it by hand as docs/agent-guidance.md lists."
    fi
    exit 0
}

cd "$app" || exit 1
if $solution; then
    mkdir -p "$work/snapshot"
    find "$app" -mindepth 1 -maxdepth 1 ! -name target ! -name .git -exec cp -a {} "$work/snapshot/" \;
    if [[ -d "$here/fixtures/$task" ]]; then cp -a "$here/fixtures/$task/." "$app/"; fi
    if ! patch -p1 --quiet --forward < "$here/solutions/$task.patch"; then
        first_failure="solution: the reference solution no longer applies to the template: redo it and record it again (record-solution.sh)"
        echo "eval-check: $task: $first_failure" >&2
        finish
    fi
fi

# --- 1, 2: the project's own tests, before the acceptance tests join them

own_tests() {
    local rc=0
    without_lock env -u DATABASE_URL cargo test --no-default-features >"$work/own-tests.log" 2>&1 || rc=$?
    cat "$work/own-tests.log"
    [[ $rc -eq 0 ]] || fail "the project's own tests fail"
}
step own-tests own_tests

tests_added() {
    local before after
    # The template's tests; none of them is gated on a feature or ignored.
    before="$(cat "$root"/templates/skilj-template/src/*.rs "$root"/templates/skilj-template/tests/*.rs |
        grep -cE '#\[(tokio::)?test')"
    # Those of the project that passed: a test gated on `local` or
    # #[ignore]d doesn't count.
    after="$(grep -hoE '^test result: [A-Za-z]+\. [0-9]+ passed' "$work/own-tests.log" 2>/dev/null |
        awk '{ sum += $4 } END { print sum + 0 }')"
    [[ "$after" -gt "$before" ]] ||
        fail "no test was added: the template has $before, $after of the project's passed"
    echo "eval-check: $task: $after tests passed, the template has $before"
}
step tests-added tests_added

# --- 3, 4: the builds, before the harness exists, so a broken acceptance
# test can't show up as a build failure

build_local() { cargo check --all-targets || fail "it doesn't build with local mode"; }
build_no_local() {
    cargo check --all-targets --no-default-features || fail "it doesn't build without local mode"
}
step build-local build_local
step build-no-local build_no_local

# --- 5: the task's own checks of the source

static_checks() {
    case "$task" in
        sensitive-field | attach-document)
            # Without a key provider, a write with a sensitive field or a
            # blob with a subject is refused (encryption_master_key_not_configured).
            grep -rq 'key_provider' src || fail "no key provider is configured, so the server can't store it"
            ;;
        unique-email)
            grep -rq 'key_provider' src || fail "no key provider is configured, so the server can't store the email"
            grep -rq 'blind_index_key' src ||
                fail "no blind index key is configured, so the server can't hash the email"
            ;;
        import-model)
            [[ -f src/savings.skilj.toml ]] || fail "there is no src/savings.skilj.toml"
            skilj-codegen check src/savings.skilj.toml || fail "skilj-codegen check refuses src/savings.skilj.toml"
            # Imported from the original model, not the project's copy.
            skilj-codegen import --from em-json "$here/fixtures/import-model/models/savings.em.json" savings \
                --output "$work/savings.imported.skilj.toml" ||
                fail "this workspace's skilj-codegen can't import the model"
            python3 "$here/compare_import.py" "$work/savings.imported.skilj.toml" src/savings.skilj.toml ||
                fail "src/savings.skilj.toml leaves out or changes what the model says (see above)"
            ;;
    esac
}
case "$task" in
    sensitive-field | attach-document | unique-email | import-model) step static static_checks ;;
    *) skip static "the task has no checks of its own" ;;
esac

# --- 6: the acceptance tests

harness_was_there=false
acceptance() {
    $harness_was_there &&
        fail "tests/skilj_eval_acceptance.rs is the project's own: the check puts its acceptance tests there, and leaves it alone"
    without_lock env -u DATABASE_URL cargo test --no-default-features --test skilj_eval_acceptance ||
        fail "the acceptance tests fail"
}
if [[ "${status[build-no-local]}" == pass ]]; then
    if [[ -e "$harness" || -L "$harness" ]]; then
        harness_was_there=true
    else
        harness_ours=true
        cp "$here/acceptance/$task.rs" "$harness"
    fi
    step acceptance acceptance
    if $harness_ours; then rm -f "$harness"; harness_ours=false; fi
else
    skip acceptance "the project doesn't build without local mode"
fi

# --- 7: the server, answering over REST

server_log=
server_pid=
servers=0
port=

# build_bin <name>: builds a binary of the project and copies it into this
# run's own directory, so another build can't replace it mid-run.
build_bin() {
    mkdir -p "$work/bin"
    cargo build --bin "$1" || fail "the $1 binary doesn't build"
    cp "$target/debug/$1" "$work/bin/$1"
}

# start_server [env arguments ...]: a start of the server on this run's
# data directory, kept between starts (SKILJ_LOCAL_CLEANUP=false whatever
# the caller's environment says), with a log of its own.
start_server() {
    servers=$((servers + 1))
    server_log="$work/server-$servers.log"
    port="$(python3 -c 'import socket; s = socket.socket(); s.bind(("127.0.0.1", 0)); print(s.getsockname()[1])')"
    # A simple command, not a function, so $! is the server itself (env
    # execs it) and Ctrl-C reaches it; without the lock's descriptor.
    env -u DATABASE_URL "$@" PORT="$port" SKILJ_LOCAL_DATA_DIR="$work/postgres" \
        SKILJ_LOCAL_CLEANUP=false "$work/bin/server" >"$server_log" 2>&1 {eval_lock_fd}>&- &
    server_pid=$!
    echo "$server_pid" >> "$work/pids"
    for _ in $(seq 1 300); do
        grep -q '^listening on ' "$server_log" && return 0
        kill -0 "$server_pid" 2>/dev/null || { cat "$server_log" >&2; fail "the server exited before it was ready"; }
        sleep 1
    done
    cat "$server_log" >&2
    fail "the server wasn't ready within 300s"
}

# stop_server: Ctrl-C, and a clean exit within 30s.
stop_server() {
    kill -INT "$server_pid"
    for _ in $(seq 1 30); do
        kill -0 "$server_pid" 2>/dev/null || break
        sleep 1
    done
    if kill -0 "$server_pid" 2>/dev/null; then
        cat "$server_log" >&2
        fail "the server didn't stop within 30s of Ctrl-C"
    fi
    wait "$server_pid" || { cat "$server_log" >&2; fail "the server exited with a failure on Ctrl-C"; }
}

# token <context>/<command type>: the token the current start printed.
token() {
    local token
    token="$(grep -oE "^  $1: [^ ]+" "$server_log" | awk '{print $2}' | tail -n 1)"
    [[ -n "$token" ]] || { cat "$server_log" >&2; fail "the server printed no token for $1"; }
    echo "$token"
}

# trigger <context>/<command type> <payload> <what the answer must contain> [header ...]
trigger() {
    local tok answer header
    local headers=()
    tok="$(token "$1")" || exit 1
    for header in "${@:4}"; do headers+=(-H "$header"); done
    answer="$(curl -sS "localhost:$port/v1/commands/trigger" -H "authorization: Bearer $tok" \
        -H 'content-type: application/json' "${headers[@]}" -d "{\"payload\":$2}")"
    [[ "$answer" == *"$3"* ]] || { cat "$server_log" >&2; fail "$1 $2 answered $answer, expected $3"; }
}

accepted='"accepted":true'
rejected() { echo "\"rejectionKind\":\"$1\""; }

# --- temporal-activity: Temporal's development server, in Docker

temporal_container=
temporal_port=

start_temporal() {
    docker info >/dev/null 2>&1 || fail "temporal-activity needs Docker, to run Temporal: start it"
    temporal_container="skilj-eval-temporal-$$-$RANDOM"
    echo "$temporal_container" >> "$work/containers"
    # Loopback only; Docker picks the host port.
    docker run -d --rm --name "$temporal_container" -p 127.0.0.1::7233 temporalio/temporal:1.5.0 \
        server start-dev --ip 0.0.0.0 >/dev/null || fail "Temporal's container didn't start"
    temporal_port="$(docker port "$temporal_container" 7233 | head -n 1 | sed 's/.*://')"
    [[ -n "$temporal_port" ]] || fail "Docker mapped no port for Temporal"
    for _ in $(seq 1 60); do
        docker exec "$temporal_container" temporal operator cluster health 2>/dev/null | grep -q SERVING &&
            return 0
        sleep 1
    done
    fail "Temporal didn't report SERVING within 60s"
}

# describe <workflow id>: what Temporal says about it; the CLI's exit code.
describe() {
    docker exec "$temporal_container" temporal workflow describe --workflow-id "$1" 2>&1
}

run_temporal_activity() {
    local answer found=false
    start_temporal
    # 1. The bridge off: w0 is opened before it is enabled.
    start_server -u TEMPORAL_ADDRESS
    trigger wallet/OpenWallet '{"wallet_id":"w0","owner_id":"o-0"}' "$accepted"
    stop_server
    # 2. The bridge on, on the same data: w1 is opened at once, before the
    # bridge has necessarily polled.
    start_server TEMPORAL_ADDRESS="127.0.0.1:$temporal_port"
    trigger wallet/OpenWallet '{"wallet_id":"w1","owner_id":"o-1"}' "$accepted"
    # w0 is still there: the first start's data was kept.
    trigger wallet/OpenWallet '{"wallet_id":"w0","owner_id":"o-0"}' "$(rejected wallet_already_open)"
    for _ in $(seq 1 60); do
        if answer="$(describe wallet:wallet:w1)" &&
            grep -qE '^ *Type +WalletOnboarding *$' <<<"$answer" &&
            grep -qE '^ *TaskQueue +wallet-onboarding *$' <<<"$answer"; then
            found=true
            break
        fi
        sleep 1
    done
    if ! $found; then
        cat "$server_log" >&2
        fail "no WalletOnboarding workflow wallet:wallet:w1 on task queue wallet-onboarding within 60s: $answer"
    fi
    # The bridge handles WalletOpened in order, so a token reading from the
    # beginning would have started w0's workflow before w1's.
    if answer="$(describe wallet:wallet:w0)"; then
        echo "$answer" >&2
        fail "w0, opened while the bridge was off, was onboarded too: the event read token reads from the beginning, not from when the bridge was enabled"
    fi
    grep -q 'workflow not found' <<<"$answer" || fail "couldn't ask Temporal about wallet:wallet:w0: $answer"
    stop_server
}

attach_document() {
    local tok reference answer
    local made_up='{"wallet_id":"w1","owner_id":"o-1","month":"2026-11","document":{"$blob":"made-up","sha256":"00","size":1,"media_type":"application/pdf"}}'
    tok="$(token wallet/AttachStatement)" || exit 1
    printf '%%PDF-1.4\n%% a statement\n%%%%EOF\n' > "$work/statement.pdf"
    reference="$(curl -sS "localhost:$port/v1/blobs/wallet?subjectKey=owner&subjectValue=o-1" \
        -H "authorization: Bearer $tok" -H 'content-type: application/pdf' \
        --data-binary "@$work/statement.pdf")"
    [[ "$reference" == *'"$blob"'* ]] || { cat "$server_log" >&2; fail "the upload answered $reference, not a reference"; }
    trigger wallet/AttachStatement \
        "{\"wallet_id\":\"w1\",\"owner_id\":\"o-1\",\"month\":\"2026-10\",\"document\":$reference}" "$accepted"
    # Read back: the month has its statement.
    trigger wallet/AttachStatement \
        "{\"wallet_id\":\"w1\",\"owner_id\":\"o-1\",\"month\":\"2026-10\",\"document\":$reference}" \
        "$(rejected statement_already_attached)"
    # A reference nobody uploaded is refused.
    answer="$(curl -sS -w '\nHTTP %{http_code}' "localhost:$port/v1/commands/trigger" \
        -H "authorization: Bearer $tok" -H 'content-type: application/json' -d "{\"payload\":$made_up}")"
    [[ "$answer" == *blob_reference_invalid*'HTTP 400' ]] ||
        fail "a made-up reference answered $answer, expected HTTP 400 blob_reference_invalid"
}

retry_idempotent() {
    local tok answer
    tok="$(token wallet/Deposit)" || exit 1
    answer="$(without_lock "$work/bin/deposit" "http://localhost:$port" "$tok" w1 100 dep-1 2>&1)" ||
        fail "the deposit binary failed: $answer"
    [[ "$answer" == *"$accepted"* ]] || fail "the first deposit answered $answer, expected $accepted"
    answer="$(without_lock "$work/bin/deposit" "http://localhost:$port" "$tok" w1 100 dep-1 2>&1)" ||
        fail "the deposit binary failed: $answer"
    [[ "$answer" == *'"deduplicated":true'* ]] ||
        fail "the same deposit again answered $answer, expected \"deduplicated\":true"
    # Booked once: 100 in the wallet, not 200.
    trigger wallet/Withdraw '{"wallet_id":"w1","amount":101}' "$(rejected insufficient_funds)"
    trigger wallet/Withdraw '{"wallet_id":"w1","amount":100}' "$accepted"
}

run_server() {
    build_bin server
    case "$task" in
        temporal-activity) run_temporal_activity; return ;;
        retry-idempotent) build_bin deposit ;;
    esac
    start_server
    case "$task" in
        add-command)
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            trigger wallet/CloseWallet '{"wallet_id":"w1"}' "$(rejected wallet_not_empty)"
            trigger wallet/Withdraw '{"wallet_id":"w1","amount":100}' "$accepted"
            trigger wallet/CloseWallet '{"wallet_id":"w1"}' "$accepted"
            # Read back from the store: these fail when WalletClosed isn't
            # decoded, or isn't tagged with the wallet.
            trigger wallet/Deposit '{"wallet_id":"w1","amount":1}' "$(rejected wallet_closed)"
            trigger wallet/CloseWallet '{"wallet_id":"w1"}' "$(rejected wallet_closed)"
            trigger wallet/Deposit '{"wallet_id":"w2","amount":1}' "$accepted"
            ;;
        evolve-event)
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":50,"reference":"rent"}' "$accepted"
            # Both deposits read back, with and without a reference.
            trigger wallet/Withdraw '{"wallet_id":"w1","amount":150}' "$accepted"
            ;;
        sensitive-field)
            trigger wallet/RegisterOwner '{"wallet_id":"w1","owner_id":"o-1","email":"ada@example.com"}' "$accepted"
            # Read back and decrypted for decide().
            trigger wallet/RegisterOwner '{"wallet_id":"w1","owner_id":"o-2","email":"grace@example.com"}' \
                "$(rejected owner_already_registered)"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            trigger wallet/Withdraw '{"wallet_id":"w1","amount":100}' "$accepted"
            ;;
        unique-email)
            trigger wallet/RegisterOwner '{"wallet_id":"w1","owner_id":"o-1","email":"ada@example.com"}' "$accepted"
            # Another wallet, the same address in capitals: the blind tag's
            # hash of the normalized address matches.
            trigger wallet/RegisterOwner '{"wallet_id":"w2","owner_id":"o-2","email":"ADA@example.com"}' \
                "$(rejected email_taken)"
            trigger wallet/RegisterOwner '{"wallet_id":"w2","owner_id":"o-2","email":"grace@example.com"}' "$accepted"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            ;;
        attach-document) attach_document ;;
        wallet-statement)
            grep -E '^reconciliation: registered ' "$server_log" | grep -q WalletStatement ||
                { cat "$server_log" >&2; fail "WalletStatement isn't registered"; }
            # A projection that fails in project() fails the write, and so
            # the command.
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            trigger wallet/Deposit '{"wallet_id":"w2","amount":30}' "$accepted"
            trigger wallet/Withdraw '{"wallet_id":"w1","amount":40}' "$accepted"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":5}' "$accepted"
            trigger wallet/Withdraw '{"wallet_id":"w2","amount":30}' "$accepted"
            ;;
        import-model)
            trigger savings/OpenGoal '{"goal_id":"g1","name":"Holiday","target_amount":500}' "$accepted"
            trigger savings/SaveTowardsGoal '{"goal_id":"g1","amount":50}' "$accepted"
            trigger savings/SaveTowardsGoal '{"goal_id":"g2","amount":50}' "$(rejected goal_not_found)"
            trigger savings/CloseGoal '{"goal_id":"g1"}' "$accepted"
            trigger savings/SaveTowardsGoal '{"goal_id":"g1","amount":50}' "$(rejected goal_closed)"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            ;;
        retry-idempotent) retry_idempotent ;;
        second-context)
            trigger rewards/EarnPoints '{"member_id":"m1","points":10}' "$accepted"
            trigger rewards/RedeemPoints '{"member_id":"m1","points":11}' "$(rejected insufficient_points)"
            trigger rewards/RedeemPoints '{"member_id":"m1","points":10}' "$accepted"
            trigger wallet/Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
            ;;
    esac
    stop_server
}

if ! $run; then
    skip run "not asked for (--run)"
elif [[ "${status[build-local]}" != pass ]]; then
    skip run "the project doesn't build with local mode"
else
    step run run_server
fi

finish
